FUNCTION_BLOCK FB
VAR_INPUT
    enable : BOOL;
    resetBtn : BOOL;
    sensorValid : BOOL;
    setpoint : REAL;
    temperature : REAL;
    scanSeconds : REAL;
    bias : REAL;
END_VAR
VAR_OUTPUT
    power : REAL;
    correction : REAL;
    fault : BOOL;
END_VAR
VAR
    ePrev : REAL := 0.0;
    historyValid : BOOL := FALSE;
    prevResetBtn : BOOL := FALSE;
    // Possibly also prevEnable and prevFault if needed for clarity.
    // But we can compute rising edge each scan.
END_VAR

Now implement logic:

```
fault := NOT sensorValid OR scanSeconds <= 0.0 OR scanSeconds > 10.0;

IF NOT enable OR fault OR (resetBtn AND NOT prevResetBtn) THEN
    // clear outputs and history
    power := 0.0;
    correction := 0.0;
    ePrev := 0.0;
    historyValid := FALSE;
ELSE
    // fuzzy control
    // compute error
    VAR e : REAL;
    VAR de : REAL;
    e := setpoint - temperature;
    IF NOT historyValid THEN
        de := 0.0;
    ELSE
        de := (e - ePrev) / scanSeconds;
    END_IF

    // normalize
    VAR x : REAL;
    VAR y : REAL;
    x := MIN(1.0, MAX(-1.0, e / 10.0));
    y := MIN(1.0, MAX(-1.0, de / 2.0));

    // membership degrees
    VAR muN_x : REAL;
    VAR muZ_x : REAL;
    VAR muP_x : REAL;
    VAR muN_y : REAL;
    VAR muZ_y : REAL;
    VAR muP_y : REAL;
    muN_x := MAX(-x, 0.0);
    muZ_x := 1.0 - ABS(x);
    muP_x := MAX(x, 0.0);
    muN_y := MAX(-y, 0.0);
    muZ_y := 1.0 - ABS(y);
    muP_y := MAX(y, 0.0);

    // rule weights
    VAR w_NN : REAL;
    VAR w_NZ : REAL;
    VAR w_NP : REAL;
    VAR w_ZN : REAL;
    VAR w_ZZ : REAL;
    VAR w_ZP : REAL;
    VAR w_PN : REAL;
    VAR w_PZ : REAL;
    VAR w_PP : REAL;
    w_NN := muN_x * muN_y;
    w_NZ := muN_x * muZ_y;
    w_NP := muN_x * muP_y;
    w_ZN := muZ_x * muN_y;
    w_ZZ := muZ_x * muZ_y;
    w_ZP := muZ_x * muP_y;
    w_PN := muP_x * muN_y;
    w_PZ := muP_x * muZ_y;
    w_PP := muP_x * muP_y;

    VAR sum_w : REAL;
    VAR sum_wc : REAL;
    sum_w := w_NN + w_NZ + w_NP + w_ZN + w_ZZ + w_ZP + w_PN + w_PZ + w_PP;

    IF sum_w > 0.0 THEN
        sum_wc := w_NN * (-30.0) + w_NZ * (-20.0) + w_NP * (-10.0) +
                  w_ZN * (-10.0) + w_ZZ * 0.0 + w_ZP * 10.0 +
                  w_PN * 10.0 + w_PZ * 20.0 + w_PP * 30.0;
        correction := sum_wc / sum_w;
    ELSE
        correction := 0.0;
    END_IF

    power := MIN(100.0, MAX(0.0, bias + correction));

    // update history
    ePrev := e;
    historyValid := TRUE;
END_IF;

 // update prevResetBtn for rising edge detection next scan
prevResetBtn := resetBtn;
```

But note that the code uses VAR e, de, x, y, muN_x etc. In IEC ST, we cannot declare local variables inside the function block's code like that (except inside the function block you can declare variables inside the VAR ... END_VAR region, but you cannot have local variables within the body that are not declared in VAR region. However, you can use intermediate variables declared in VAR region at the top of the function block, or you can reuse them across calls. That's fine.

