FUNCTION_BLOCK FB
VAR_INPUT
    enable : BOOL;
    resetBtn : BOOL;
    sensorValid : BOOL;
    setpoint : REAL;
    temperature : REAL;
    scanSeconds : REAL;
    bias : REAL;
END_VAR
VAR_OUTPUT
    power : REAL;
    correction : REAL;
    fault : BOOL;
END_VAR
VAR
    ePrev : REAL := 0.0;
    historyValid : BOOL := FALSE;
    prevResetBtn : BOOL := FALSE;
    // intermediate variables
    e : REAL;
    de : REAL;
    x : REAL;
    y : REAL;
    muN_x : REAL;
    muZ_x : REAL;
    muP_x : REAL;
    muN_y : REAL;
    muZ_y : REAL;
    muP_y : REAL;
    w_NN : REAL;
    w_NZ : REAL;
    w_NP : REAL;
    w_ZN : REAL;
    w_ZZ : REAL;
    w_ZP : REAL;
    w_PN : REAL;
    w_PZ : REAL;
    w_PP : REAL;
    sum_w : REAL;
    sum_wc : REAL;
END_VAR

// Compute fault condition
fault := NOT sensorValid OR scanSeconds <= 0.0 OR scanSeconds > 10.0;

// If disabled, fault or reset rising edge → reset outputs and clear history
IF NOT enable OR fault OR (resetBtn AND NOT prevResetBtn) THEN
    power := 0.0;
    correction := 0.0;
    ePrev := 0.0;
    historyValid := FALSE;
ELSE
    // Compute error and derivative
    e := setpoint - temperature;
    IF NOT historyValid THEN
        de := 0.0;
    ELSE
        de := (e - ePrev) / scanSeconds;
    END_IF;

    // Normalize error and derivative
    x := MIN(1.0, MAX(-1.0, e / 10.0));
    y := MIN(1.0, MAX(-1.0, de / 2.0));

    // Membership functions for x
    muN_x := MAX(-x, 0.0);
    muZ_x := 1.0 - ABS(x);
    muP_x := MAX(x, 0.0);

    // Membership functions for y
    muN_y := MAX(-y, 0.0);
    muZ_y := 1.0 - ABS(y);
    muP_y := MAX(y, 0.0);

    // Rule weights (product of memberships)
    w_NN := muN_x * muN_y;
    w_NZ := muN_x * muZ_y;
    w_NP := muN_x * muP_y;
    w_ZN := muZ_x * muN_y;
    w_ZZ := muZ_x * muZ_y;
    w_ZP := muZ_x * muP_y;
    w_PN := muP_x * muN_y;
    w_PZ := muP_x * muZ_y;
    w_PP := muP_x * muP_y;

    // Weighted sum of rule outputs
    sum_w := w_NN + w_NZ + w_NP + w_ZN + w_ZZ + w_ZP + w_PN + w_PZ + w_PP;

    IF sum_w > 0.0 THEN
        sum_wc := w_NN * (-30.0) + w_NZ * (-20.0) + w_NP * (-10.0) +
                  w_ZN * (-10.0) + w_ZZ * 0.0 + w_ZP * 10.0 +
                  w_PN * 10.0 + w_PZ * 20.0 + w_PP * 30.0;
        correction := sum_wc / sum_w;
    ELSE
        correction := 0.0;
    END_IF;

    // Compute power output, clamped to 0..100
    power := MIN(100.0, MAX(0.0, bias + correction));

    // Store error for next scan
    ePrev := e;
    historyValid := TRUE;
END_IF;

// Update previous reset button state for edge detection
prevResetBtn := resetBtn;

END_FUNCTION_BLOCK
